head.script:
// 전역 변수
let refreshInterval;
scwin.selectedTenantId = null;

scwin.getApiToken = function () {
    return sessionStorage.getItem('accessToken');
};

scwin.onpageload = function () {
    console.log("향상된 서버 현황 페이지 로드");
    scwin.showDefaultData();
    scwin.loadTenantList();
    // scwin.testConnection();

    setTimeout(function () {
        scwin.loadServerData();
    }, 1000);

    refreshInterval = setInterval(function () {
        scwin.loadServerData();
    }, 30000);
};

scwin.onpageunload = function () {
    if (refreshInterval) {
        clearInterval(refreshInterval);
    }
};

scwin.loadTenantList = function () {
    console.log("=== 테넌트 목록 로드 시작 ===");
    $p.hideProcessMessage();
    $p.executeSubmission("sbm_selectTenantVoList");
};

scwin.sbm_selectTenantVoList_submitdone = function (e) {
    $p.hideProcessMessage();
    console.log("=== 테넌트 목록 조회 성공 ===");

    const totalCount = e.responseJSON.elData.totalCount || 0;
    dmp_tenantVo.set("totalRowCount", totalCount);

    scwin.updatePagination();

    if (dlt_tenantVoList.getRowCount() > 0) {
        const firstTenantId = dlt_tenantVoList.getCellData(0, "tenantId");
        grd_tenantList.setFocusedCell(0, "name");

        const firstTenantData = {
            tenantId: dlt_tenantVoList.getCellData(0, "tenantId"),
            name: dlt_tenantVoList.getCellData(0, "name"),
            subDomain: dlt_tenantVoList.getCellData(0, "subDomain"),
            createdAt: dlt_tenantVoList.getCellData(0, "createdAt"),
            isActive: dlt_tenantVoList.getCellData(0, "isActive")
        };

        scwin.updateTenantDetailInfo(firstTenantData);
        scwin.loadTenantData(firstTenantId);

        scwin.selectedTenantId = firstTenantId;
    } else {
        scwin.updateTenantStats({ sessions: "-", users: "-" });
        scwin.hideTenantDetailInfo();

        scwin.selectedTenantId = null;
    }
};

scwin.formatActiveStatus = function (data) {
    console.log("상태 포맷팅:", data, typeof data);

    if (data === true || data === 'true' || data === 1 || data === '1' || data === 'Y' || data === 'y') {
        return "활성";
    } else if (data === false || data === 'false' || data === 0 || data === '0' || data === 'N' || data === 'n') {
        return "비활성";
    }

    return "비활성";
};

scwin.sbm_selectTenantVoList_submiterror = function (e) {
    console.error("=== 테넌트 목록 조회 실패 ===", e);
};

scwin.testConnection = function () {
    console.log("네트워크 연결 테스트 중...");

    try {
        fetch('https://unify-conference.store/ws/api/admin/server-stats', {
            method: 'GET',
            headers: {
                'Authorization': scwin.getApiToken(),
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            mode: 'cors',
            timeout: 10000
        })
            .then(response => {
                console.log("연결 테스트 응답:", response.status);
                if (!response.ok) {
                    throw new Error(`HTTP ${response.status}: ${response.statusText}`);
                }
                return response.json();
            })
            .then(data => {
                console.log("연결 테스트 성공:", data);
                scwin.handleApiSuccess(data);
            })
            .catch(error => {
                console.error("연결 테스트 실패:", error);
                scwin.handleConnectionError(error);
            });
    } catch (error) {
        console.error("Fetch 지원 불가:", error);
        scwin.fallbackToXMLHttpRequest();
    }
};

scwin.fallbackToXMLHttpRequest = function () {
    console.log("XMLHttpRequest 사용하여 API 호출...");

    const xhr = new XMLHttpRequest();
    xhr.open('GET', 'https://unify-conference.store/ws/api/admin/server-stats', true);

    xhr.setRequestHeader('Authorization', 'Bearer ' + scwin.getApiToken());
    xhr.setRequestHeader('Content-Type', 'application/json');
    xhr.setRequestHeader('Accept', 'application/json');

    xhr.timeout = 10000;

    xhr.onreadystatechange = function () {
        if (xhr.readyState === 4) {
            if (xhr.status === 200) {
                try {
                    const data = JSON.parse(xhr.responseText);
                    console.log("XMLHttpRequest 성공:", data);
                    scwin.handleApiSuccess(data);
                } catch (parseError) {
                    console.error("JSON 파싱 오류:", parseError);
                    scwin.handleApiError("응답 데이터 파싱 실패");
                }
            } else {
                console.error("XMLHttpRequest 오류:", xhr.status, xhr.statusText);
                scwin.handleHttpError(xhr.status, xhr.statusText);
            }
        }
    };

    xhr.onerror = function () {
        console.error("XMLHttpRequest 네트워크 오류");
        scwin.handleApiError("네트워크 연결 오류");
    };

    xhr.ontimeout = function () {
        console.error("XMLHttpRequest 타임아웃");
        scwin.handleApiError("요청 시간 초과");
    };

    try {
        xhr.send();
    } catch (sendError) {
        console.error("XMLHttpRequest 전송 오류:", sendError);
        scwin.handleApiError("요청 전송 실패");
    }
};

scwin.handleConnectionError = function (error) {
    let errorMessage = "서버 연결 실패";

    if (error.name === 'TypeError' && error.message.includes('fetch')) {
        errorMessage = "네트워크 오류 또는 CORS 정책으로 인한 차단";
    } else if (error.message.includes('403')) {
        errorMessage = "인증 실패 - API 토큰을 확인해주세요";
    } else if (error.message.includes('404')) {
        errorMessage = "API 엔드포인트를 찾을 수 없습니다";
    } else if (error.message.includes('500')) {
        errorMessage = "서버 내부 오류";
    }

    scwin.handleApiError(errorMessage);
    console.log("Fetch 실패, XMLHttpRequest로 재시도...");
    setTimeout(scwin.fallbackToXMLHttpRequest, 1000);
};

scwin.handleHttpError = function (status, statusText) {
    let errorMessage = `HTTP ${status} 오류`;

    switch (status) {
        case 0:
            errorMessage = "네트워크 연결 불가 또는 CORS 차단";
            break;
        case 401:
            errorMessage = "인증 실패 - 로그인이 필요합니다";
            break;
        case 403:
            errorMessage = "접근 권한이 없습니다 - 토큰을 확인해주세요";
            break;
        case 404:
            errorMessage = "API 엔드포인트를 찾을 수 없습니다";
            break;
        case 500:
            errorMessage = "서버 내부 오류";
            break;
        case 502:
            errorMessage = "서버가 응답하지 않습니다";
            break;
        case 503:
            errorMessage = "서비스를 사용할 수 없습니다";
            break;
        default:
            errorMessage = `HTTP ${status}: ${statusText}`;
    }

    scwin.handleApiError(errorMessage);
};

scwin.handleApiSuccess = function (data) {
    console.log("=== API 응답 성공 ===");
    console.log("실제 API 데이터:", data);

    try {
        if (!data || !data.summary) {
            throw new Error("API 응답에 summary 데이터가 없습니다.");
        }

        const formattedData = {
            activeSessions: data.summary.activeRoomCount || 0,
            connectedUsers: data.summary.totalConnectedPeers || 0,
            activeWorkers: data.workers ? data.workers.length : 0,
            uptime: data.summary.uptime || 0,
            serverStatus: "정상",

            memoryUsage: scwin.parseMemoryPercentage(data.summary.memoryUsage?.rssPercentOfSystem),
            cpuUsage: scwin.calculateCpuFromWorkers(data.workers),
            networkUsage: scwin.calculateNetworkFromActivity(data.summary),

            workers: data.workers ? data.workers.map((worker, index) => ({
                pid: worker.pid,
                status: 'running',
                memoryMb: worker.memoryUsage?.maxRssMb || 'N/A',
                cpuUser: worker.cpuTime?.user || 0,
                cpuSystem: worker.cpuTime?.system || 0
            })) : [],

            sessions: data.rooms ? data.rooms.map(room => ({
                roomName: room.id || 'Unknown Room',
                sessionId: room.id,
                participantCount: room.peersCount || 0,
                duration: scwin.getRandomDuration(),
                quality: scwin.getQualityByParticipants(room.peersCount || 0)
            })) : [],

            systemMemoryMB: data.summary.memoryUsage?.totalSystemMemoryMB || 'N/A',
            processMemoryMB: data.summary.memoryUsage?.rssMB || 'N/A',
            totalTransports: data.summary.totalTransports || 0,
            totalProducers: data.summary.totalProducers || 0,
            totalConsumers: data.summary.totalConsumers || 0
        };

        console.log("UI에 맞게 변환된 데이터:", formattedData);

        scwin.updateServerStats(formattedData);
        scwin.updatePerformanceIndicators(formattedData);
        scwin.updateSystemInfo(formattedData);
        scwin.updateWorkerProcesses(formattedData.workers);
        scwin.updateLiveSessions(formattedData.sessions);

        scwin.showLoading(false);
        console.log("=== 실제 데이터로 UI 업데이트 완료 ===");

    } catch (error) {
        console.error("데이터 처리 오류:", error);
        scwin.handleApiError("데이터 처리 중 오류가 발생했습니다: " + error.message);
    }
};

scwin.parseMemoryPercentage = function (percentString) {
    if (!percentString) return 0;
    return parseFloat(percentString.replace('%', '')) || 0;
};

scwin.calculateCpuFromWorkers = function (workers) {
    if (!workers || workers.length === 0) return 0;

    let totalCpuTime = 0;
    workers.forEach(worker => {
        if (worker.cpuTime) {
            totalCpuTime += (worker.cpuTime.user || 0) + (worker.cpuTime.system || 0);
        }
    });

    return Math.min(Math.floor(totalCpuTime / 1000), 100);
};

scwin.calculateNetworkFromActivity = function (summary) {
    const transports = summary.totalTransports || 0;
    const producers = summary.totalProducers || 0;
    const consumers = summary.totalConsumers || 0;

    const transportLoad = transports * 2;
    const producerLoad = producers * 5;
    const consumerLoad = consumers * 3;

    return Math.min(transportLoad + producerLoad + consumerLoad, 100);
};

scwin.updateSystemInfo = function (data) {
    try {
        console.log("시스템 정보 업데이트:", data);
        console.log(`시스템 메모리: ${data.systemMemoryMB}MB`);
        console.log(`프로세스 메모리: ${data.processMemoryMB}MB`);
        console.log(`메모리 사용률: ${data.memoryUsage}%`);
        console.log(`총 Transport: ${data.totalTransports}`);
        console.log(`총 Producer: ${data.totalProducers}`);
        console.log(`총 Consumer: ${data.totalConsumers}`);
    } catch (error) {
        console.error("시스템 정보 업데이트 오류:", error);
    }
};

scwin.updateWorkerProcesses = function (workers) {
    try {
        console.log("Worker 프로세스 업데이트:", workers);

        const workerSection = document.getElementById("worker_process_section");
        if (workerSection) {
            const existingItems = workerSection.querySelectorAll('.worker-item');
            existingItems.forEach(item => item.remove());

            workers.forEach((worker, index) => {
                const workerItem = document.createElement('div');
                workerItem.className = 'worker-item';
                workerItem.innerHTML = `
                    <div class="worker-icon icon-worker">W${index + 1}</div>
                    <div class="worker-info">
                        <div class="worker-name">Worker #${index + 1}</div>
                        <div class="worker-details">PID: ${worker.pid} | 메모리: ${worker.memoryMb}MB</div>
                    </div>
                    <div class="worker-metrics">
                        <div class="worker-load">CPU: ${worker.cpuUser + worker.cpuSystem}ms</div>
                        <div class="worker-sessions">실행중</div>
                    </div>
                `;
                workerSection.appendChild(workerItem);
            });

            if (workers.length === 0) {
                const noWorkerItem = document.createElement('div');
                noWorkerItem.className = 'worker-item';
                noWorkerItem.innerHTML = `
                    <div class="worker-info">
                        <div class="worker-name">활성 Worker가 없습니다</div>
                    </div>
                `;
                workerSection.appendChild(noWorkerItem);
            }
        }
    } catch (error) {
        console.error("Worker 프로세스 UI 업데이트 오류:", error);
    }
};

scwin.showDefaultData = function () {
    console.log("기본 데이터 표시");
    const defaultData = {
        activeSessions: 0,
        connectedUsers: 0,
        activeWorkers: 0,
        uptime: 0,
        serverStatus: "로딩중",
        cpuUsage: 0,
        memoryUsage: 0,
        networkUsage: 0,
        workers: [],
        sessions: []
    };
    scwin.updateServerStats(defaultData);
    scwin.updatePerformanceIndicators(defaultData);
    scwin.updateWorkerProcesses(defaultData.workers);
    scwin.updateLiveSessions(defaultData.sessions);
    scwin.updateTenantStats({ sessions: 0, users: 0 });
};

scwin.loadServerData = function () {
    console.log("서버 데이터 로드 시도...");
    scwin.showLoading(true);
    scwin.testConnection();
};

scwin.loadTenantData = function (tenantId) {
    if (!tenantId) {
        scwin.updateTenantStats({ sessions: "전체", users: "전체" });
        return;
    }

    console.log(`테넌트 ${tenantId} 데이터 로드 시도`);
    const url = `https://unify-conference.store/ws/api/admin/tenant-stats?tenantId=${tenantId}`;
    scwin.updateTenantStats({ sessions: "로딩중...", users: "로딩중..." });

    fetch(url, {
        method: 'GET',
        headers: {
            'Authorization': scwin.getApiToken(),
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        },
        mode: 'cors'
    })
        .then(response => {
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            return response.json();
        })
        .then(data => {
            console.log("테넌트 데이터 로드 성공:", data);

            const tenantData = {
                sessions: data.activeRooms || 0,
                users: data.connectedPeers || 0
            };

            scwin.updateTenantStats(tenantData);
        })
        .catch(error => {
            console.error("테넌트 데이터 로드 실패:", error);
            scwin.updateTenantStats({ sessions: "오류", users: "오류" });
            scwin.loadTenantDataXHR(tenantId);
        });
};

scwin.loadTenantDataXHR = function (tenantId) {
    console.log("XMLHttpRequest로 테넌트 데이터 재시도...");

    const xhr = new XMLHttpRequest();
    const url = `https://unify-conference.store/ws/api/admin/tenant-stats?tenantId=${tenantId}`;

    xhr.open('GET', url, true);
    xhr.setRequestHeader('Authorization', 'Bearer ' + scwin.getApiToken());
    xhr.setRequestHeader('Content-Type', 'application/json');
    xhr.timeout = 10000;

    xhr.onreadystatechange = function () {
        if (xhr.readyState === 4) {
            if (xhr.status === 200) {
                try {
                    const data = JSON.parse(xhr.responseText);
                    console.log("테넌트 XHR 성공:", data);
                    const tenantData = {
                        sessions: data.activeSessions || data.summary?.activeRoomCount || 0,
                        users: data.connectedUsers || data.summary?.totalConnectedPeers || 0
                    };
                    scwin.updateTenantStats(tenantData);
                } catch (parseError) {
                    console.error("테넌트 데이터 파싱 오류:", parseError);
                    scwin.updateTenantStats({ sessions: "파싱오류", users: "파싱오류" });
                }
            } else {
                console.error("테넌트 XHR 오류:", xhr.status, xhr.statusText);
                scwin.updateTenantStats({ sessions: `HTTP ${xhr.status}`, users: "오류" });
            }
        }
    };

    xhr.onerror = function () {
        console.error("테넌트 XHR 네트워크 오류");
        scwin.updateTenantStats({ sessions: "네트워크오류", users: "네트워크오류" });
    };

    xhr.ontimeout = function () {
        console.error("테넌트 XHR 타임아웃");
        scwin.updateTenantStats({ sessions: "타임아웃", users: "타임아웃" });
    };

    try {
        xhr.send();
    } catch (sendError) {
        console.error("테넌트 XHR 전송 오류:", sendError);
        scwin.updateTenantStats({ sessions: "전송오류", users: "전송오류" });
    }
};

scwin.loadSessionInfo = function (roomId) {
    console.log(`${roomId} 세션의 상세 정보를 요청합니다.`);

    const url = `https://unify-conference.store/ws/api/admin/session-info?roomId=${roomId}`;

    fetch(url, {
        method: 'GET',
        headers: {
            'Authorization': 'Bearer ' + scwin.getApiToken(),
            'Content-Type': 'application/json'
        }
    })
        .then(response => {
            if (!response.ok) {
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            }
            return response.json();
        })
        .then(data => {
            console.log("세션 상세 정보:", data);
            const detailInfo = `세션 상세 정보:
룸 ID: ${data.roomId || roomId}
참여자 수: ${data.participants || 0}명
지속 시간: ${data.duration || 'N/A'}
상태: ${data.status || '활성'}
품질 지표: ${data.quality || '정상'}
비트레이트: ${data.bitrate || 'N/A'} kbps
패킷 손실률: ${data.packetLoss || 'N/A'}%`;

            alert(detailInfo);
        })
        .catch(error => {
            console.error("세션 정보 로드 실패:", error);
            alert("세션 정보를 불러올 수 없습니다: " + error.message);
        });
};

scwin.updateServerStats = function (data) {
    try {
        console.log("서버 통계 업데이트:", data);

        setTimeout(() => {
            const statNumbers = document.querySelectorAll('.stat-number');
            console.log("stat-number 요소들:", statNumbers.length);

            if (statNumbers.length >= 4) {
                statNumbers[0].textContent = data.activeSessions || "0";
                statNumbers[1].textContent = data.connectedUsers || "0";
                statNumbers[2].textContent = data.activeWorkers || "0";
                statNumbers[3].textContent = scwin.formatUptime(data.uptime);
                console.log("클래스 선택자로 서버 통계 업데이트 성공");
            }

            const statusTextEl = document.querySelector('.status-text');
            if (statusTextEl) {
                statusTextEl.textContent = data.serverStatus || "정상";
            }

            const statusDotEl = document.querySelector('.status-dot');
            if (statusDotEl) {
                const isHealthy = data.serverStatus === "정상";
                statusDotEl.style.backgroundColor = isHealthy ? "#34c759" : "#ff3b30";
            }

        }, 50);

    } catch (error) {
        console.error("서버 통계 UI 업데이트 오류:", error);
    }
};

scwin.updatePerformanceIndicators = function (data) {
    try {
        console.log("성능 지표 업데이트:", data);

        const cpuUsage = Math.round(data.cpuUsage || 0);
        const memoryUsage = Math.round(data.memoryUsage || 0);
        const networkUsage = Math.round(data.networkUsage || 0);

        console.log(`계산된 값들 - CPU: ${cpuUsage}%, 메모리: ${memoryUsage}%, 네트워크: ${networkUsage}%`);

        try {
            const cpuTextComp = $p.getComponentById("cpuText");
            if (cpuTextComp) {
                cpuTextComp.setValue(cpuUsage + '%');
                console.log("CPU 텍스트 웹스퀘어 컴포넌트 업데이트 성공:", cpuUsage + '%');
            }
        } catch (e) {
            console.log("CPU 텍스트 웹스퀘어 컴포넌트 접근 실패:", e);
        }

        try {
            const memoryTextComp = $p.getComponentById("memoryText");
            if (memoryTextComp) {
                memoryTextComp.setValue(memoryUsage + '%');
                console.log("메모리 텍스트 웹스퀘어 컴포넌트 업데이트 성공:", memoryUsage + '%');
            }
        } catch (e) {
            console.log("메모리 텍스트 웹스퀘어 컴포넌트 접근 실패:", e);
        }

        try {
            const networkTextComp = $p.getComponentById("networkText");
            if (networkTextComp) {
                networkTextComp.setValue(networkUsage + '%');
                console.log("네트워크 텍스트 웹스퀘어 컴포넌트 업데이트 성공:", networkUsage + '%');
            }
        } catch (e) {
            console.log("네트워크 텍스트 웹스퀘어 컴포넌트 접근 실패:", e);
        }

        setTimeout(() => {
            try {
                const cpuBar = document.querySelector('#cpuBar, [id*="cpuBar"]');
                const memoryBar = document.querySelector('#memoryBar, [id*="memoryBar"]');
                const networkBar = document.querySelector('#networkBar, [id*="networkBar"]');

                if (cpuBar) {
                    cpuBar.style.width = cpuUsage + '%';
                    console.log("CPU 바 직접 업데이트 성공");
                }
                if (memoryBar) {
                    memoryBar.style.width = memoryUsage + '%';
                    console.log("메모리 바 직접 업데이트 성공");
                }
                if (networkBar) {
                    networkBar.style.width = networkUsage + '%';
                    console.log("네트워크 바 직접 업데이트 성공");
                }

                const performanceTexts = document.querySelectorAll('.performance-text');
                console.log("performance-text 요소들:", performanceTexts.length);

                if (performanceTexts.length >= 3) {
                    performanceTexts[0].textContent = cpuUsage + '%';
                    performanceTexts[1].textContent = memoryUsage + '%';
                    performanceTexts[2].textContent = networkUsage + '%';
                    console.log("클래스 선택자로 텍스트 업데이트 성공");
                }

            } catch (domError) {
                console.error("DOM 직접 접근 오류:", domError);
            }
        }, 100);

        try {
            const totalTransportsComp = $p.getComponentById('totalTransports');
            const totalProducersComp = $p.getComponentById('totalProducers');
            const totalConsumersComp = $p.getComponentById('totalConsumers');

            if (totalTransportsComp) totalTransportsComp.setValue(data.totalTransports || 0);
            if (totalProducersComp) totalProducersComp.setValue(data.totalProducers || 0);
            if (totalConsumersComp) totalConsumersComp.setValue(data.totalConsumers || 0);

            console.log("시스템 정보 웹스퀘어 컴포넌트 업데이트 완료");
        } catch (e) {
            console.log("시스템 정보 웹스퀘어 컴포넌트 접근 실패:", e);
        }

    } catch (error) {
        console.error("성능 지표 업데이트 오류:", error);
    }
};

scwin.updateTenantStats = function (data) {
    try {
        console.log("테넌트 통계 업데이트:", data);

        const sessionValue = data.activeSessions || data.sessions || "0";
        const userValue = data.connectedUsers || data.users || "0";

        try {
            const sessionsComp = $p.getComponentById('tenantSessions');
            if (sessionsComp) {
                sessionsComp.setValue(sessionValue);
                console.log("테넌트 세션 웹스퀘어 컴포넌트 업데이트:", sessionValue);
            }
        } catch (e) {
            console.log("테넌트 세션 웹스퀘어 컴포넌트 접근 실패:", e);
        }

        try {
            const usersComp = $p.getComponentById('tenantUsers');
            if (usersComp) {
                usersComp.setValue(userValue);
                console.log("테넌트 사용자 웹스퀘어 컴포넌트 업데이트:", userValue);
            }
        } catch (e) {
            console.log("테넌트 사용자 웹스퀘어 컴포넌트 접근 실패:", e);
        }

        setTimeout(() => {
            const tenantStatNumbers = document.querySelectorAll('.tenant-stat-number');
            if (tenantStatNumbers.length >= 2) {
                tenantStatNumbers[0].textContent = sessionValue;
                tenantStatNumbers[1].textContent = userValue;
                console.log("클래스 선택자로 테넌트 통계 업데이트 성공");
            }
        }, 50);

    } catch (error) {
        console.error("테넌트 통계 업데이트 오류:", error);
    }
};

scwin.updateLiveSessions = function (sessions) {
    try {
        const sessionSection = document.getElementById("live_session_section");
        if (sessionSection) {
            const existingItems = sessionSection.querySelectorAll('.worker-item');
            existingItems.forEach(item => item.remove());

            sessions.forEach(session => {
                const sessionItem = document.createElement('div');
                sessionItem.className = 'worker-item';
                sessionItem.style.cursor = 'pointer';
                sessionItem.onclick = function () {
                    scwin.loadSessionInfo(session.sessionId);
                };

                const iconClass = scwin.getSessionIconClass(session.roomName);
                const iconText = scwin.getSessionIconText(session.roomName);

                sessionItem.innerHTML = `
                    <div class="worker-icon ${iconClass}">${iconText}</div>
                    <div class="worker-info">
                        <div class="worker-name">${session.roomName || 'Unknown Room'}</div>
                        <div class="worker-details">지속시간: ${session.duration} | 품질: ${session.quality}</div>
                    </div>
                    <div class="worker-metrics">
                        <div class="worker-load">${session.participantCount || 0}명</div>
                        <div class="worker-sessions">참여중</div>
                    </div>
                `;
                sessionSection.appendChild(sessionItem);
            });
        }
    } catch (error) {
        console.error("라이브 세션 UI 업데이트 오류:", error);
    }
};

scwin.onTenantSelectChange = function (row, col) {
    const tenantId = dlt_tenantVoList.getCellData(row, "tenantId");

    if (tenantId && tenantId === scwin.selectedTenantId) {
        console.log(`동일 테넌트(${tenantId}) 재클릭: 상세 정보 숨김`);
        scwin.hideTenantDetailInfo();    
        scwin.selectedTenantId = null;  
        grd_tenantList.setFocusedCell(-1, -1);
        return;
    }

    const tenantData = {
        tenantId: tenantId,
        name: dlt_tenantVoList.getCellData(row, "name"),
        subDomain: dlt_tenantVoList.getCellData(row, "subDomain"),
        createdAt: dlt_tenantVoList.getCellData(row, "createdAt"),
        isActive: dlt_tenantVoList.getCellData(row, "isActive")
    };

    console.log(`=== GridView 행 클릭: ${row}번째 행, tenantId: ${tenantId} ===`);

    if (tenantId) {
        scwin.selectedTenantId = tenantId;

        scwin.updateTenantDetailInfo(tenantData);
        scwin.loadTenantData(tenantId);
    } else {
        console.error("클릭된 행의 tenantId를 찾을 수 없습니다.");
        scwin.hideTenantDetailInfo();
        scwin.selectedTenantId = null; // 선택 상태 초기화
    }
};

scwin.updateTenantDetailInfo = function (tenantData) {
    try {
        const detailSectionComp = $p.getComponentById("tenant_detail_section");
        if (detailSectionComp) {
            detailSectionComp.setStyle("display", "block");
        }

        const detailTenantId = $p.getComponentById('detail_tenant_id');
        if (detailTenantId) detailTenantId.setValue(tenantData.tenantId || '-');

        const detailName = $p.getComponentById('detail_name');
        if (detailName) detailName.setValue(tenantData.name || '-');

        const detailSubdomain = $p.getComponentById('detail_subdomain');
        if (detailSubdomain) detailSubdomain.setValue(tenantData.subDomain || '-');

        const detailCreatedAt = $p.getComponentById('detail_created_at');
        if (detailCreatedAt) {
            const formattedDate = scwin.formatDateTime(tenantData.createdAt);
            detailCreatedAt.setValue(formattedDate);
        }

        const detailIsActive = $p.getComponentById('detail_is_active');
        if (detailIsActive) {
            const statusText = scwin.formatActiveStatus(tenantData.isActive);
            detailIsActive.setValue(statusText);

        }

        console.log("테넌트 상세 정보 업데이트 완료:", tenantData);

    } catch (error) {
        console.error("테넌트 상세 정보 업데이트 오류:", error);
    }
};

scwin.hideTenantDetailInfo = function () {
    const detailSectionComp = $p.getComponentById("tenant_detail_section");
    if (detailSectionComp) {
        detailSectionComp.setStyle("display", "none");
    }
};
scwin.formatDateTime = function (dateTimeString) {
    if (!dateTimeString) return '-';

    try {
        const date = new Date(dateTimeString);
        if (isNaN(date.getTime())) return dateTimeString;

        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const day = String(date.getDate()).padStart(2, '0');
        const hours = String(date.getHours()).padStart(2, '0');
        const minutes = String(date.getMinutes()).padStart(2, '0');

        return `${year}-${month}-${day} ${hours}:${minutes}`;
    } catch (error) {
        console.error("날짜 포맷팅 오류:", error);
        return dateTimeString;
    }
};

scwin.formatUptime = function (seconds) {
    if (!seconds || seconds < 60) return `${Math.floor(seconds || 0)}초`;
    if (seconds < 3600) return `${Math.floor(seconds / 60)}분`;
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}시간 ${minutes}분`;
};

scwin.getRandomDuration = function () {
    const minutes = Math.floor(Math.random() * 120 + 10);
    if (minutes < 60) return `${minutes}분`;
    const hours = Math.floor(minutes / 60);
    const remainingMinutes = minutes % 60;
    return `${hours}시간 ${remainingMinutes}분`;
};

scwin.getRandomUptime = function () {
    const hours = Math.floor(Math.random() * 72 + 1);
    return `${hours}시간`;
};

scwin.getQualityByParticipants = function (count) {
    if (count > 30) return "보통";
    if (count > 15) return "우수";
    return "최고";
};

scwin.getSessionIconClass = function (roomName) {
    if (roomName.includes('회의') || roomName.includes('meeting')) return 'icon-meeting';
    if (roomName.includes('수업') || roomName.includes('class')) return 'icon-class';
    if (roomName.includes('세미나') || roomName.includes('seminar')) return 'icon-seminar';
    return 'icon-session';
};

scwin.getSessionIconText = function (roomName) {
    if (roomName.includes('회의') || roomName.includes('meeting')) return 'M';
    if (roomName.includes('수업') || roomName.includes('class')) return 'C';
    if (roomName.includes('세미나') || roomName.includes('seminar')) return 'S';
    return 'S';
};

scwin.showLoading = function (show) {
    try {
        document.querySelectorAll('.worker-refresh-btn').forEach(btn => {
            btn.disabled = show;
            btn.textContent = show ? '로딩중...' : '새로고침';
        });
        document.querySelectorAll('.stat-card').forEach(card => {
            if (show) card.classList.add('loading');
            else card.classList.remove('loading');
        });
    } catch (error) {
        console.error("로딩 상태 표시 오류:", error);
    }
};

scwin.handleApiError = function (message) {
    console.error("API 오류:", message);
    scwin.showLoading(false);

    const statusEl = document.querySelector('.status-text');
    if (statusEl) statusEl.textContent = "오류";
    const statusDotEl = document.querySelector('.status-dot');
    if (statusDotEl) statusDotEl.style.backgroundColor = "#ff3b30";

    alert("오류: " + message);
};

scwin.serverStatsSuccess = function (e) {
    console.log("WebSquare submission 성공:", e);
    try {
        const realData = e.responseJSON || JSON.parse(e.responseText);
        scwin.handleApiSuccess(realData);
    } catch (error) {
        console.error("WebSquare submission 데이터 처리 오류:", error);
        scwin.handleApiError("WebSquare submission 데이터 처리 실패");
    }
};

scwin.tenantStatsSuccess = function (e) {
