scwin.updatePagination = function () {
    const txt_pageInfo = $p.getComponentById("txt_pageInfo");
    const btn_prevPage = $p.getComponentById("btn_prevPage");
    const btn_nextPage = $p.getComponentById("btn_nextPage");

    const currentPage = parseInt(dmp_tenantVo.get("pageIndex"), 10);
    const totalRows = parseInt(dmp_tenantVo.get("totalRowCount"), 10);
    const pageSize = parseInt(dmp_tenantVo.get("pageSize"), 10);
    const totalPages = Math.ceil(totalRows / pageSize) || 1;

    txt_pageInfo.setValue(`${currentPage} / ${totalPages}`);

    btn_prevPage.setDisabled(currentPage <= 1);
    btn_nextPage.setDisabled(currentPage >= totalPages);
};

scwin.changeTenantPage = function (direction) {
    let currentPage = parseInt(dmp_tenantVo.get("pageIndex"), 10);
    const totalPages = Math.ceil(parseInt(dmp_tenantVo.get("totalRowCount"), 10) / parseInt(dmp_tenantVo.get("pageSize"), 10)) || 1;

    if (direction === 'prev' && currentPage > 1) {
        currentPage--;
    } else if (direction === 'next' && currentPage < totalPages) {
        currentPage++;
    } else {
        return;
    }

    dmp_tenantVo.set("pageIndex", currentPage);
    scwin.loadTenantList();
};
